// Detect trigger source: voice (Webhook Retell) vs chatbot (executeWorkflow)
let isVoiceTrigger = false;
try { $('Webhook Retell').item; isVoiceTrigger = true; } catch(e) {}

let contacid = '';
try { contacid = $('When Executed by Another Workflow').item.json.contacid; } catch(e) {}
if (!contacid) { try { contacid = $('Edit Fields Retell').item.json.contacid; } catch(e) {} }
if (!contacid) {
  try {
    const lead = $('Get list of leads1').item.json._embedded?.leads?.[0];
    contacid = String(lead?._embedded?.contacts?.[0]?.id || '');
  } catch(e) {}
}

const date = new Date();
const fmt = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid', weekday: 'long', hour: 'numeric', minute: 'numeric', hour12: false
});
const parts = {};
fmt.formatToParts(date).forEach(p => parts[p.type] = p.value);
const hour = parseInt(parts.hour);
const minute = parseInt(parts.minute);
const weekday = parts.weekday.toLowerCase();
const total = hour * 60 + minute;
const isWeekday = !['sábado','domingo'].includes(weekday);
const isOpen = isWeekday && ((total >= 600 && total < 840) || (total >= 930 && total < 1230));

let motivo = '';
try { motivo = $('When Executed by Another Workflow').item.json.motivo || ''; } catch(e) {}
if (!motivo) { try { motivo = $('Edit Fields Retell').item.json.motivo || ''; } catch(e) {} }
if (!motivo) motivo = 'Paciente derivado por asistente virtual';

return [{ json: { isOpen, contacid, isVoiceTrigger, motivo } }];

